/bin/bash -lc "cd [workspace path] && python3 -c \"
import numpy as np
rgb = np.load('source_pixels.npz')['rgb']
def bluemask(f):
    r,g,b=f[...,0].astype(int),f[...,1].astype(int),f[...,2].astype(int)
    return (b>r+40)&(b>g+30)&(b>100)
for fi in range(0,96,4):
    m=bluemask(rgb[fi])
    ys,xs=np.where(m)
    if len(xs):
        print(f'{fi:2d} n={m.sum():4d} x[{xs.min():3d},{xs.max():3d}] y[{ys.min():3d},{ys.max():3d}] cx={xs.mean():6.1f} cy={ys.mean():6.1f}')
    else:
        print(fi,'none')
\""
